CREATE TABLE IF NOT EXISTS deduplicated_reagent_catalog AS 
SELECT DISTINCT * FROM reagent_catalog; 

INSERT INTO shared_export (recipient_org) 
VALUES ('lab_inventory');

CREATE TABLE IF NOT EXISTS reagent_catalog (
    id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    CAS TEXT NOT NULL,
    quantity INTEGER
);

DROP TABLE IF EXISTS deduplicated_reagent_catalog; 
CREATE TABLE deduplicated_reagent_catalog (
    name TEXT,
    CAS TEXT,
    total_quantity INTEGER
); 

INSERT INTO deduplicated_reagent_catalog (name, CAS, total_quantity) 
SELECT name, CAS, SUM(quantity) AS total_quantity 
FROM reagent_catalog 
GROUP BY CAS;

